// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address owner = address(uint160(0xE0A));

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != owner);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // owner opens the contract
        vm.prank(owner, owner);
        c.OpenToThePublic();

        // a real person (msg.sender == tx.origin) places the (zero-limit) wager
        vm.deal(actor, 1 ether);
        vm.prank(actor, actor);
        bool ok;
        try c.wager{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Once opened, wagering by any real person must succeed.
        assertTrue(ok);
    }
}
